import{_ as a,c as d,o as s,a0 as e}from"./chunks/framework.C1J0Vcxi.js";const _=JSON.parse('{"title":"K3 GMAC 网卡驱动调试教训","description":"","frontmatter":{"title":"K3 GMAC 网卡驱动调试教训","date":"2026-08-14","author":"Oveln"},"headers":[],"relativePath":"技术报告/2026-08-14-K3-GMAC驱动调试教训.md","filePath":"技术报告/2026-08-14-K3-GMAC驱动调试教训.md"}'),i={name:"技术报告/2026-08-14-K3-GMAC驱动调试教训.md"};function o(n,t,r,h,l,c){return s(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="k3-gmac-网卡驱动调试教训" tabindex="-1">K3 GMAC 网卡驱动调试教训 <a class="header-anchor" href="#k3-gmac-网卡驱动调试教训" aria-label="Permalink to &quot;K3 GMAC 网卡驱动调试教训&quot;">​</a></h1><h2 id="_0-背景" tabindex="-1">0. 背景 <a class="header-anchor" href="#_0-背景" aria-label="Permalink to &quot;0. 背景&quot;">​</a></h2><p>K3 COM260 开发板上，我需要让 StarryOS（基于 ArceOS 的通用内核）的以太网口可用， 以支持 DHCP、网络文件系统等服务。硬件为进迭时空 K3 SoC，搭载 DWMAC 5.10a 以太网 MAC IP + RTL8211F PHY，通过 RGMII 接口连接。</p><p>U-Boot 阶段 TFTP 工作正常，证明硬件没问题。但自己写的 GMAC 驱动在 StarryOS 上长期 无法工作：PHY 自协商完成、链路 UP，但 DHCP 始终超时。这个驱动我反复调试了跨多个 session、数十次真板测试，最终定位到<strong>三个独立的寄存器定义/地址错误</strong>，逐一修复后 驱动终于可用——DHCP 成功、ping 成功。</p><p>本文是我对这段调试经历的复盘：走过的弯路、最终找到的三个 bug、以及由此沉淀的教训。</p><hr><h2 id="_1-症状" tabindex="-1">1. 症状 <a class="header-anchor" href="#_1-症状" aria-label="Permalink to &quot;1. 症状&quot;">​</a></h2><p>驱动初始化日志显示一切&quot;正常&quot;：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>k3-gmac: PHY0 link state: up=true speed=1000Mbps duplex=full</span></span>
<span class="line"><span>k3-gmac: after start_dma: TX_ST=true chan_stat=0x84</span></span>
<span class="line"><span>k3-gmac: post-init: GMAC_CONFIG=0x00072203 (RE=true TE=true DM=true ...)</span></span>
<span class="line"><span>         TX_CTRL=0x00080011 (ST=true OSP=true) RX_CTRL=0x00081001 (SR=true RBSZ=2048)</span></span>
<span class="line"><span>k3-gmac: TX#0 desc[0] des3=0xb0000131(OWN=true) | tail wrote=0xfcf64040 readback=0xfcf64040</span></span>
<span class="line"><span>         cur_tx=0xfcf64000 chan_stat=0x84(TBU=true FBE=false) dbg0=0x1300</span></span></code></pre></div><p>我在驱动里加了诊断日志，关键信息是：</p><ul><li>TX 描述符 OWN=1（CPU 已交由 DMA），但 DMA 从不清除 OWN</li><li><code>cur_tx</code>（DMA 当前读取位置）始终停在 ring base，从不前进</li><li><code>dbg0=0x1300</code>：TX DMA 引擎状态机处于 <strong>Idle（状态 0）</strong>，从未启动</li><li>RX 路径在特定配置下能收到包（说明 DMA AXI 总线、EAME、地址解码都正常）</li></ul><p><strong>核心矛盾</strong>：TX_CTRL 的 ST=1（启动位已设），tail pointer 已正确写入，描述符 OWN=1， 但 TX DMA 引擎就是不读描述符。</p><hr><h2 id="_2-调试历程与发现的三个-bug" tabindex="-1">2. 调试历程与发现的三个 Bug <a class="header-anchor" href="#_2-调试历程与发现的三个-bug" aria-label="Permalink to &quot;2. 调试历程与发现的三个 Bug&quot;">​</a></h2><h3 id="_2-1-探索阶段-大量试错排除假根因" tabindex="-1">2.1 探索阶段：大量试错排除假根因 <a class="header-anchor" href="#_2-1-探索阶段-大量试错排除假根因" aria-label="Permalink to &quot;2.1 探索阶段：大量试错排除假根因&quot;">​</a></h3><p>早期我走了很多弯路，靠&quot;推测哪个寄存器可能有问题 → 改 → 上板测&quot;的方式排查， 测了大量假设：</p><table tabindex="0"><thead><tr><th>假设</th><th>验证方式</th><th>结论</th></tr></thead><tbody><tr><td>DMA 软复位缺失导致引擎锁死</td><td>对照 U-Boot <code>eqos_start</code>，恢复 <code>reset_dma</code></td><td>软复位成功，但 TX 仍不工作（非根因，但保留）</td></tr><tr><td>DMA 软复位导致引擎锁死</td><td>移除软复位</td><td>无变化（非根因）</td></tr><tr><td><code>update()</code>（RMW）保留了 U-Boot 残留位</td><td>改为绝对写（<code>write</code>）</td><td><strong>让 RX 工作了</strong>（消除了残留），但 TX 仍不工作</td></tr><tr><td>EAME 未启用（&gt;4GB DMA 寻址）</td><td>检查 <code>DMA_SYS_BUS_MODE</code> bit11</td><td>已启用，非根因</td></tr><tr><td><code>DMA_MASK=u32::MAX</code>（32 位）</td><td>K3 无 &lt;4GB DRAM，改回 u64::MAX</td><td>修复了 NoMemory，非 TX 根因</td></tr><tr><td><code>DMA_AXI_BUS_MODE</code> 错误偏移</td><td>合并到 <code>DMA_SYS_BUS_MODE</code></td><td>修正了寄存器布局，非 TX 根因</td></tr><tr><td>PBL=0 无突发</td><td>加 PBL=8</td><td>正确修复，非 TX 根因</td></tr><tr><td><code>DMA_CHAN_CONTROL</code>（PBLX8+DSL）未写</td><td>加绝对写</td><td>正确修复，非 TX 根因</td></tr><tr><td>TX buffer cache 未 flush</td><td>检查 <code>prepare_for_device</code></td><td>已 flush，非根因</td></tr><tr><td>Zicbom CMO 未真正执行</td><td>追踪 feature 链</td><td>已启用，非根因</td></tr><tr><td>描述符格式错误</td><td>对照 <code>dwmac4_descs.h</code> 逐位检查</td><td>格式正确，非根因</td></tr><tr><td>RISC-V IOMMU 阻塞</td><td>检查 DTS <code>iommus</code> 属性</td><td>GMAC 无 IOMMU 绑定，pass-through 模式，非根因</td></tr></tbody></table><p>十几个假设全部排除了。这个阶段我反复上板测试，效率很低，而且每次测试结果都是 &quot;TX 还是不工作&quot;，无法区分到底是哪个改动起了作用。</p><p><strong>转折点</strong>：我决定不再猜测，而是让 AI 助手做一次 U-Boot <code>eqos_start</code> + Linux <code>stmmac_hw_setup</code> vs 我的 <code>init_hardware</code> 的<strong>逐行寄存器写入对照</strong>，系统性地列出 每一个差异。正是这次穷尽的对照找到了最终的 bug。</p><h3 id="_2-2-bug-1-mtl-op-mode-tsf-位定义错误" tabindex="-1">2.2 Bug #1：<code>MTL_OP_MODE_TSF</code> 位定义错误 <a class="header-anchor" href="#_2-2-bug-1-mtl-op-mode-tsf-位定义错误" aria-label="Permalink to &quot;2.2 Bug #1：\`MTL_OP_MODE_TSF\` 位定义错误&quot;">​</a></h3><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 我的错误定义：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MTL_OP_MODE_TSF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> u32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// BIT0 是 FTQ（Flush TX Queue）！</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 正确（对照 U-Boot BIT(1) + Linux BIT(1)）：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MTL_OP_MODE_TSF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> u32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// BIT1 才是 TSF（Store-and-Forward）</span></span></code></pre></div><p>BIT0 在 MTL TX 操作模式寄存器中是 <strong>FTQ（Flush TX Queue）</strong>——我写 1 进去等于持续 flush TX 队列，DMA 写入 TX FIFO 的数据被立即丢弃。</p><p>这个 bug 是逐行对照 U-Boot <code>dwc_eth_qos.h:114-115</code> 时发现的：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EQOS_MTL_TXQ0_OPERATION_MODE_TSF</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    BIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EQOS_MTL_TXQ0_OPERATION_MODE_FTQ</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    BIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>但修了它 TX 还是不工作</strong>。它是加重因素，不是终极根因。</p><h3 id="_2-3-bug-2-dma-软复位缺失-次要修复" tabindex="-1">2.3 Bug #2：DMA 软复位缺失（次要修复） <a class="header-anchor" href="#_2-3-bug-2-dma-软复位缺失-次要修复" aria-label="Permalink to &quot;2.3 Bug #2：DMA 软复位缺失（次要修复）&quot;">​</a></h3><p>DMA 软复位（<code>DMA_BUS_MODE</code> bit0，写 1 后硬件自清）能重启 DMA 内部状态机。我之前 错误地移除了它——当时误以为&quot;U-Boot 不做软复位&quot;，实际上 U-Boot 在 <code>eqos_start</code> 最开头就做（line 767-773），Linux 的 <code>stmmac_hw_setup</code> 也是。</p><p>加回软复位后，日志确认 <code>DMA soft reset completed after 257773 iterations</code>（~258ms）， 但 TX 仍然不工作。这个修复对照参考实现是正确的，但不是 TX 不工作的根因。</p><h3 id="_2-4-bug-3-mtl-chan-base-addr-错误-终极根因-⭐" tabindex="-1">2.4 Bug #3：<code>MTL_CHAN_BASE_ADDR</code> 错误（终极根因）⭐ <a class="header-anchor" href="#_2-4-bug-3-mtl-chan-base-addr-错误-终极根因-⭐" aria-label="Permalink to &quot;2.4 Bug #3：\`MTL_CHAN_BASE_ADDR\` 错误（终极根因）⭐&quot;">​</a></h3><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 我的错误定义：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MTL_CHAN_BASE_ADDR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> u32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0xc00</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 正确（对照 U-Boot EQOS_MTL_REGS_BASE + Linux MTL_CHAN_BASE_ADDR）：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MTL_CHAN_BASE_ADDR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> u32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0xd00</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>这是终极根因。<strong>我所有的 MTL 寄存器写入（TX 队列使能 TSF|TXQEN|TQS、RX 队列 RSF|RQS 等）都写到了错误地址</strong>——<code>0xc00</code> 而非 <code>0xd00</code>。MTL TX 队列从未被使能， TXQEN 位写到了不存在的地址，硬件 MTL TX 队列保持默认的禁用状态。</p><p><strong>怎么发现的</strong>：修了 TSF 位定义后 TX 还是不工作，逐行对照报告确认&quot;寄存器初始化 序列在所有控制 TX DMA fetch 的位上都是正确的&quot;，迫使我转向 MTL 层。最终在检查 MTL TX debug 寄存器偏移时，我注意到 U-Boot 定义 <code>EQOS_MTL_REGS_BASE = 0xd00</code> （<code>dwc_eth_qos.h:96</code>），而我的代码用 <code>0xc00</code>——差了整整 0x100。</p><p><strong>为什么 TX 不工作而 RX 工作</strong>：DWMAC4 硬件中，<strong>RX 队列默认使能</strong>（复位后 RXQ0EN 默认值非零），<strong>TX 队列默认禁用</strong>（复位后 TXQEN=0）。RX 不依赖我写错的 MTL 配置 （默认就开了），TX 必须显式使能但我写错了地址。这完美解释了一直困扰我的 &quot;RX 工作、TX 不工作&quot;的不对称现象。</p><p><strong>DMA 引擎为何 Idle</strong>：DMA 引擎 fetch 描述符后，需要把数据写入 MTL TX FIFO。但 MTL TX 队列未被使能，MTL 拒绝接收 DMA 数据。DMA 的写入路径被阻塞，fetch engine 因此停滞在 Idle 状态——<code>cur_tx</code> 从不前进，<code>dbg0</code> TX state=0。</p><h3 id="_2-5-修复确认" tabindex="-1">2.5 修复确认 <a class="header-anchor" href="#_2-5-修复确认" aria-label="Permalink to &quot;2.5 修复确认&quot;">​</a></h3><p>三个 Bug 修复后，真板测试结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>k3-gmac: TX#0 desc[0] ... cur_tx=0xfcf64040  ← cur_tx 前进了！</span></span>
<span class="line"><span>eth0: DHCP bound: 192.168.1.100/24           ← DHCP 成功！</span></span>
<span class="line"><span>ping 192.168.1.1: 64 bytes, time=0.5ms       ← ping 成功！</span></span></code></pre></div><p>驱动终于工作了。</p><hr><h2 id="_3-为什么调试这么久-——教训总结" tabindex="-1">3. 为什么调试这么久？——教训总结 <a class="header-anchor" href="#_3-为什么调试这么久-——教训总结" aria-label="Permalink to &quot;3. 为什么调试这么久？——教训总结&quot;">​</a></h2><p>整个调试过程跨越了多个 session、数十次真板测试。反思为何耗时如此之长：</p><h3 id="教训-1-不要在没有参考源码的情况下猜测硬件行为" tabindex="-1">教训 1：不要在没有参考源码的情况下猜测硬件行为 <a class="header-anchor" href="#教训-1-不要在没有参考源码的情况下猜测硬件行为" aria-label="Permalink to &quot;教训 1：不要在没有参考源码的情况下猜测硬件行为&quot;">​</a></h3><p>早期我大量依赖&quot;推测&quot;——猜哪个寄存器可能有问题，改了就上板测。这导致了大量的 试错循环（见 §2.1 的表格，列出了十几个被排除的假根因），每次真板测试 5-10 分钟， 效率极低。</p><p><strong>正确做法</strong>：第一时间找到参考实现（U-Boot / Linux 源码），逐行对照。本次调试的 转折点正是让 AI 助手做 U-Boot <code>eqos_start</code> vs 我的 <code>init_hardware</code> 的逐行寄存器 写入对照。这种系统性的 diff 比任何猜测都有效。</p><p>对于 SoC 外设驱动移植，U-Boot 驱动（尤其是同一厂商的 SDK）是最可靠的参考，因为 U-Boot 初始化序列通常最精简、最直接，没有 Linux 的抽象层（stmmac_ops 等）。 <strong>先对照 U-Boot，再对照 Linux</strong>。</p><h3 id="教训-2-寄存器地址和位定义必须逐个对照源码-不能凭记忆-猜测" tabindex="-1">教训 2：寄存器地址和位定义必须逐个对照源码，不能凭记忆/猜测 <a class="header-anchor" href="#教训-2-寄存器地址和位定义必须逐个对照源码-不能凭记忆-猜测" aria-label="Permalink to &quot;教训 2：寄存器地址和位定义必须逐个对照源码，不能凭记忆/猜测&quot;">​</a></h3><p>三个 Bug 都是<strong>常量定义错误</strong>（<code>MTL_CHAN_BASE_ADDR</code> 差 0x100、<code>MTL_OP_MODE_TSF</code> 差 1 位）。这类错误编译器无法发现，运行时的症状又很模糊（&quot;DMA 不工作&quot;），极难定位。</p><p><strong>正确做法</strong>：新建驱动时，每一个寄存器偏移量和位定义都应该从参考头文件直接对照 （<code>dwmac4.h</code>、<code>dwmac4_dma.h</code>、<code>dwc_eth_qos.h</code>），而不是凭记忆或&quot;差不多&quot;写。建一个 对照表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| 我的常量 | 值 | Linux/U-Boot 对应 | 参考值 | 一致？ |</span></span>
<span class="line"><span>|-----------|-----|-------------------|--------|--------|</span></span>
<span class="line"><span>| MTL_CHAN_BASE_ADDR | 0xc00 | EQOS_MTL_REGS_BASE | 0xd00 | ❌ |</span></span>
<span class="line"><span>| MTL_OP_MODE_TSF | BIT(0) | EQOS_..._TSF | BIT(1) | ❌ |</span></span></code></pre></div><p>在驱动开发的寄存器定义阶段就做这种对照，能避免后期数天的调试。</p><h3 id="教训-3-不对称现象-部分工作-是重要线索-要深入解释" tabindex="-1">教训 3：不对称现象（部分工作）是重要线索，要深入解释 <a class="header-anchor" href="#教训-3-不对称现象-部分工作-是重要线索-要深入解释" aria-label="Permalink to &quot;教训 3：不对称现象（部分工作）是重要线索，要深入解释&quot;">​</a></h3><p>&quot;RX 工作但 TX 不工作&quot;这个现象在调试早期就出现了，但我没有深入追问&quot;为什么&quot;。 如果早一点追问&quot;什么硬件机制能让 RX 默认工作但 TX 不工作&quot;，可能更快定位到 MTL 队列 使能的问题。</p><p><strong>正确做法</strong>：当观察到不对称现象（一个方向工作、另一个不工作）时，列出所有 &quot;RX 和 TX 的不同点&quot;，包括：</p><ul><li>硬件默认状态（RX 队列默认开 vs TX 队列默认关）</li><li>配置依赖（RX 需要什么、TX 需要什么）</li><li>代码路径差异（<code>submit_rx</code> 有 SR doorbell，<code>submit_tx</code> 没有）</li></ul><p>不对称现象通常指向配置差异或默认值差异，值得专门深入。</p><h3 id="教训-4-诊断日志要包含-引擎状态-而不只是-配置状态" tabindex="-1">教训 4：诊断日志要包含&quot;引擎状态&quot;而不只是&quot;配置状态&quot; <a class="header-anchor" href="#教训-4-诊断日志要包含-引擎状态-而不只是-配置状态" aria-label="Permalink to &quot;教训 4：诊断日志要包含&quot;引擎状态&quot;而不只是&quot;配置状态&quot;&quot;">​</a></h3><p>早期诊断日志主要打印配置寄存器的值（TX_CTRL、CHAN_CTRL 等），这些值看起来都正确， 但无法反映 DMA 引擎的实际运行状态。</p><p><strong>正确做法</strong>：加入 DMA 引擎状态寄存器的诊断：</p><ul><li><code>DMA_DEBUG_STATUS_0</code>（0x100c）：TX/RX DMA 引擎状态机状态</li><li><code>DMA_CHAN_CUR_TX_DESC</code>（0x1144）：DMA 当前正在处理的描述符地址</li><li><code>MTL_CHAN_TX_DEBUG</code>：MTL TX 队列状态</li></ul><p>这些寄存器直接反映引擎&quot;在做什么&quot;而非&quot;配了什么&quot;。<code>dbg0=0x1300</code>（TX state=Idle）和 <code>cur_tx=base</code>（从不前进）是定位问题的关键信号。</p><p>诊断日志应该回答&quot;引擎为什么不工作&quot;，而不只是&quot;配置是否正确&quot;。</p><h3 id="教训-5-逐行对照时要警惕确认偏差" tabindex="-1">教训 5：逐行对照时要警惕确认偏差 <a class="header-anchor" href="#教训-5-逐行对照时要警惕确认偏差" aria-label="Permalink to &quot;教训 5：逐行对照时要警惕确认偏差&quot;">​</a></h3><p>人眼对照源码容易&quot;看到自己期望看到的&quot;——确认偏差。我多次&quot;确认&quot;过寄存器定义&quot;正确&quot;， 但实际上 MTL base 地址和 TSF 位都是错的。</p><p><strong>正确做法</strong>：让 AI 助手做自动化的逐行对照，输出结构化的 diff 表格。机器不受确认 偏差影响，会忠实地报告每一个差异。对于复杂的源码对照任务，穷尽的 diff 比人工 对照更可靠。</p><h3 id="教训-6-真板测试成本高-改代码前要做足推演" tabindex="-1">教训 6：真板测试成本高，改代码前要做足推演 <a class="header-anchor" href="#教训-6-真板测试成本高-改代码前要做足推演" aria-label="Permalink to &quot;教训 6：真板测试成本高，改代码前要做足推演&quot;">​</a></h3><p>每次真板测试需要刷写固件、重启开发板、观察串口日志，耗时 5-10 分钟。大量&quot;试错式&quot; 修改导致测试效率极低——这也是我在调试中途明确要求&quot;测试之前严格进行代码推演， 保证测试有必要的进展&quot;的原因。</p><p><strong>正确做法</strong>：每次提交测试前，应该明确：</p><ol><li>当前修改的假设是什么</li><li>这个假设有什么源码证据</li><li>如果假设错误，诊断日志能否区分</li></ol><p>尊重真板测试的成本，把调试的&quot;不确定性&quot;消化在代码推演阶段，而不是测试阶段。</p><hr><h2 id="_4-调试方法论沉淀" tabindex="-1">4. 调试方法论沉淀 <a class="header-anchor" href="#_4-调试方法论沉淀" aria-label="Permalink to &quot;4. 调试方法论沉淀&quot;">​</a></h2><p>基于本次经验，我总结出 SoC 外设驱动调试的标准流程：</p><h3 id="第一阶段-参照源码-动手前" tabindex="-1">第一阶段：参照源码（动手前） <a class="header-anchor" href="#第一阶段-参照源码-动手前" aria-label="Permalink to &quot;第一阶段：参照源码（动手前）&quot;">​</a></h3><ol><li><strong>找到参考实现</strong>：U-Boot SDK 驱动 &gt; Linux mainline 驱动 &gt; 数据手册</li><li><strong>逐行对照初始化序列</strong>：列出每一个寄存器写入的对照表</li><li><strong>特别关注常量定义</strong>：寄存器偏移量、位位置、位掩码——这些是最容易出错且最难发现的地方</li></ol><h3 id="第二阶段-诊断设计-第一次测试前" tabindex="-1">第二阶段：诊断设计（第一次测试前） <a class="header-anchor" href="#第二阶段-诊断设计-第一次测试前" aria-label="Permalink to &quot;第二阶段：诊断设计（第一次测试前）&quot;">​</a></h3><ol><li><strong>打印引擎状态</strong>：不只是配置寄存器，还要有状态机状态、当前指针位置</li><li><strong>打印不对称信息</strong>：如果 TX 和 RX 路径类似，对比两者的诊断输出</li><li><strong>设计可区分的诊断</strong>：每次测试应该能排除至少一个假设</li></ol><h3 id="第三阶段-迭代调试" tabindex="-1">第三阶段：迭代调试 <a class="header-anchor" href="#第三阶段-迭代调试" aria-label="Permalink to &quot;第三阶段：迭代调试&quot;">​</a></h3><ol><li><strong>一次只改一个变量</strong>：不要同时改多个地方</li><li><strong>解释所有现象</strong>：特别是&quot;部分工作&quot;的不对称现象</li><li><strong>用穷尽对照代替猜测</strong>：当人眼对照无法定位时，做自动化逐行 diff</li></ol><hr><blockquote><p>分支完整代码分析和工作内容总结见周报 <a href="./../周报-Oveln/2026-08-14-周报三十三.html">《第三十三周：K3 GMAC 网卡驱动调试成功 + AMP IPC 链路修复》</a>。</p></blockquote><hr><h2 id="_5-附录-关键寄存器速查" tabindex="-1">5. 附录：关键寄存器速查 <a class="header-anchor" href="#_5-附录-关键寄存器速查" aria-label="Permalink to &quot;5. 附录：关键寄存器速查&quot;">​</a></h2><h3 id="dma-块-基址偏移-0x1000" tabindex="-1">DMA 块（基址偏移 0x1000） <a class="header-anchor" href="#dma-块-基址偏移-0x1000" aria-label="Permalink to &quot;DMA 块（基址偏移 0x1000）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>寄存器</th><th>偏移</th><th>说明</th></tr></thead><tbody><tr><td>DMA_BUS_MODE</td><td>0x1000</td><td>bit0=SWR（软复位）</td></tr><tr><td>DMA_SYS_BUS_MODE</td><td>0x1004</td><td>EAME(bit11) + BLEN + OSR</td></tr><tr><td>DMA_DEBUG_STATUS_0</td><td>0x100c</td><td>bits[3:0]=TX state, [19:16]=RX state</td></tr></tbody></table><h3 id="dma-channel-0-基址-0x1100-stride-0x80" tabindex="-1">DMA Channel 0（基址 0x1100，stride 0x80） <a class="header-anchor" href="#dma-channel-0-基址-0x1100-stride-0x80" aria-label="Permalink to &quot;DMA Channel 0（基址 0x1100，stride 0x80）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>寄存器</th><th>偏移</th><th>说明</th></tr></thead><tbody><tr><td>DMA_CHAN_CONTROL</td><td>0x1100</td><td>PBLX8(bit16) + DSL(bits[20:18])</td></tr><tr><td>DMA_CHAN_TX_CONTROL</td><td>0x1104</td><td>ST(bit0) + OSP(bit4) + PBL(bits[21:16])</td></tr><tr><td>DMA_CHAN_RX_CONTROL</td><td>0x1108</td><td>SR(bit0) + RBSZ(bits[14:1]) + RXPBL(bits[21:16])</td></tr><tr><td>DMA_CHAN_TX_BASE_HI</td><td>0x1110</td><td>描述符环基址高 32 位</td></tr><tr><td>DMA_CHAN_TX_BASE</td><td>0x1114</td><td>描述符环基址低 32 位</td></tr><tr><td>DMA_CHAN_RX_BASE_HI</td><td>0x1118</td><td></td></tr><tr><td>DMA_CHAN_RX_BASE</td><td>0x111c</td><td></td></tr><tr><td>DMA_CHAN_TX_END</td><td>0x1120</td><td>TX 尾指针（doorbell）</td></tr><tr><td>DMA_CHAN_RX_END</td><td>0x1128</td><td>RX 尾指针</td></tr><tr><td>DMA_CHAN_TX_RING_LEN</td><td>0x112c</td><td>TX 环长度（N-1）</td></tr><tr><td>DMA_CHAN_RX_RING_LEN</td><td>0x1130</td><td>RX 环长度（N-1）</td></tr><tr><td>DMA_CHAN_INTR_ENA</td><td>0x1134</td><td>中断使能</td></tr><tr><td>DMA_CHAN_CUR_TX_DESC</td><td>0x1144</td><td>DMA 当前 TX 描述符（只读）</td></tr><tr><td>DMA_CHAN_STATUS</td><td>0x1160</td><td>TI(bit0) TBU(bit2) RI(bit6) RBU(bit7)</td></tr></tbody></table><h3 id="mtl-channel-0-基址-0xd00-stride-0x40" tabindex="-1">MTL Channel 0（基址 0xd00，stride 0x40） <a class="header-anchor" href="#mtl-channel-0-基址-0xd00-stride-0x40" aria-label="Permalink to &quot;MTL Channel 0（基址 0xd00，stride 0x40）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>寄存器</th><th>偏移</th><th>说明</th></tr></thead><tbody><tr><td>MTL_CHAN_TX_OP_MODE</td><td>0xd00</td><td>TSF(bit1) FTQ(bit0!) TXQEN(bits[3:2]) TQS(bits[24:16])</td></tr><tr><td>MTL_CHAN_TX_DEBUG</td><td>0xd08</td><td>TX 队列状态</td></tr><tr><td>MTL_CHAN_RX_OP_MODE</td><td>0xd30</td><td>RSF(bit5) RQS(bits[29:20])</td></tr></tbody></table><h3 id="mac-基址-0x0000" tabindex="-1">MAC（基址 0x0000） <a class="header-anchor" href="#mac-基址-0x0000" aria-label="Permalink to &quot;MAC（基址 0x0000）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>寄存器</th><th>偏移</th><th>说明</th></tr></thead><tbody><tr><td>GMAC_CONFIG</td><td>0x0000</td><td>RE(bit0) TE(bit1) DM(bit13) FES(bit14) PS(bit15)</td></tr><tr><td>GMAC_PACKET_FILTER</td><td>0x0008</td><td>PR(bit0) PM(bit1)</td></tr><tr><td>GMAC_RXQ_CTRL0</td><td>0x00a0</td><td>RXQ0EN(bits[1:0])，DCB=2</td></tr><tr><td>GMAC_ADDR_HIGH0</td><td>0x0300</td><td>MAC 地址高 16 位 + AE(bit31)</td></tr><tr><td>GMAC_ADDR_LOW0</td><td>0x0304</td><td>MAC 地址低 32 位</td></tr><tr><td>GMAC_VERSION</td><td>0x0310</td><td>synopsys_id（0x54 = DWMAC 5.10a）</td></tr><tr><td>GMAC_HW_FEATURE0-3</td><td>0x0358+</td><td>硬件特性（FIFO 大小、地址宽度等）</td></tr></tbody></table><hr><h2 id="_6-参考源码索引" tabindex="-1">6. 参考源码索引 <a class="header-anchor" href="#_6-参考源码索引" aria-label="Permalink to &quot;6. 参考源码索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参考源</th><th>路径</th><th>关键函数</th></tr></thead><tbody><tr><td>U-Boot</td><td><code>drivers/net/dwc_eth_qos.c</code></td><td><code>eqos_start()</code>（初始化）、<code>eqos_send()</code>（TX）、<code>eqos_recv()</code>（RX）</td></tr><tr><td>U-Boot</td><td><code>drivers/net/dwc_eth_qos.h</code></td><td>寄存器定义 + 位定义</td></tr><tr><td>Linux</td><td><code>drivers/net/ethernet/stmicro/stmmac/stmmac_main.c</code></td><td><code>stmmac_hw_setup()</code>、<code>stmmac_xmit()</code></td></tr><tr><td>Linux</td><td><code>drivers/net/ethernet/stmicro/stmmac/dwmac4_dma.c</code></td><td><code>dwmac4_dma_init()</code>、<code>dwmac4_dma_reset()</code></td></tr><tr><td>Linux</td><td><code>drivers/net/ethernet/stmicro/stmmac/dwmac4_lib.c</code></td><td><code>dwmac4_dma_start_tx()</code>、<code>dwmac4_set_tx_tail_ptr()</code></td></tr><tr><td>Linux</td><td><code>drivers/net/ethernet/stmicro/stmmac/dwmac4_descs.c</code></td><td><code>dwmac4_rd_prepare_tx_desc()</code>、<code>dwmac4_set_tx_owner()</code></td></tr><tr><td>Linux</td><td><code>drivers/net/ethernet/stmicro/stmmac/dwmac4.h</code></td><td>MAC/MTL 寄存器定义</td></tr><tr><td>Linux</td><td><code>drivers/net/ethernet/stmicro/stmmac/dwmac4_dma.h</code></td><td>DMA 寄存器 + 位定义</td></tr></tbody></table><hr><p><em>文档完成于 2026-08-14。基于 K3 COM260 开发板真板调试。</em></p>`,95)])])}const u=a(i,[["render",o]]);export{_ as __pageData,u as default};
